insert into questions (level, category, question_text, options, correct_option_index, explanation) values
(1, 'logic', 'Tomas, Hana and Yuki sit on a bench. Tomas is on the far left and Hana is on the far right. Who sits in the middle?', '["Tomas", "Hana", "Yuki", "Nobody"]', 2, 'Tomas takes the left end and Hana takes the right end, so Yuki must be in the middle seat.'),
(1, 'logic', 'There are 5 kids in a line and Jaya is exactly in the middle. What place in line is Jaya?', '["2nd", "3rd", "4th", "5th"]', 1, 'With 2 kids in front and 2 kids behind, Jaya is 3rd.'),
(1, 'logic', 'Ali is 4th in the lunch line. Bea stands right behind him. What place is Bea in?', '["3rd", "4th", "6th", "5th"]', 3, 'Right behind 4th means the next number, which is 5th.'),
(1, 'logic', 'Six kids stand in a line and Kofi is at the very back. How many kids are in front of Kofi?', '["5", "6", "4", "1"]', 0, 'There are 6 kids in all. Everyone except Kofi is in front of him, so 6 - 1 = 5.'),
(1, 'logic', 'Sasha is 2nd from the front of a line. Ines stands directly in front of her. What place is Ines in?', '["2nd", "1st", "3rd", "4th"]', 1, 'The place just in front of 2nd is 1st.'),
(1, 'logic', 'Nia finished a race just before Owen. Owen came 5th. What place did Nia come?', '["3rd", "5th", "6th", "4th"]', 3, 'Just before 5th is 4th, so Nia came 4th.'),
(1, 'logic', 'A shelf holds a red, green, blue, yellow and purple book in that order from left to right. Which book is in the middle?', '["Green", "Yellow", "Blue", "Red"]', 2, 'The order is red, green, blue, yellow, purple. Blue is 3rd of 5, right in the middle.'),
(1, 'logic', 'Tara is 2nd from the front and also 2nd from the back of a line. How many kids are in the line?', '["3", "2", "4", "5"]', 0, 'Tara has 1 kid in front and 1 kid behind her, so with her that makes 3 kids.'),
(1, 'logic', 'Leo is standing on step 4 of the stairs. He climbs up 2 more steps. Which step is he on now?', '["Step 2", "Step 5", "Step 8", "Step 6"]', 3, 'Going up adds steps: 4 + 2 = 6.'),
(1, 'logic', 'Kai is on step 6 of the stairs and walks down 3 steps. Which step is he on now?', '["Step 9", "Step 4", "Step 3", "Step 2"]', 2, 'Going down takes steps away: 6 - 3 = 3.'),
(1, 'logic', 'An elevator starts on floor 2 and goes up 3 floors. Which floor does it stop at?', '["Floor 5", "Floor 6", "Floor 4", "Floor 1"]', 0, 'Counting up from 2: 3, 4, 5. It stops on floor 5.'),
(1, 'logic', 'The school is 2nd house on the street and the library is 4th. Which house is between them?', '["1st house", "3rd house", "5th house", "2nd house"]', 1, 'Between 2nd and 4th is 3rd.'),
(1, 'logic', 'Amir is ahead of Beth in a line. Beth is ahead of Chen. Chen is ahead of Dara. Who is 2nd in line?', '["Amir", "Chen", "Beth", "Dara"]', 2, 'The order is Amir, Beth, Chen, Dara. Beth is 2nd.'),
(1, 'logic', 'Four birds sit on a fence. The robin is left of the sparrow, the sparrow is left of the crow, and the crow is left of the owl. Which bird is 2nd from the left?', '["Robin", "Crow", "Owl", "Sparrow"]', 3, 'From left to right: robin, sparrow, crow, owl. The sparrow is 2nd.'),
(1, 'logic', 'The bakery is left of the school. The school is left of the park. Which one is in the middle?', '["The school", "The bakery", "The park", "Cannot tell"]', 0, 'The order is bakery, school, park, so the school is in the middle.'),
(1, 'logic', 'Ten kids run a race and Pablo finishes 10th. How many kids finished ahead of him?', '["10", "9", "8", "1"]', 1, 'Pablo is last of 10, so the other 9 kids finished before him.'),
(1, 'logic', 'Two days after Friday comes which day?', '["Saturday", "Monday", "Thursday", "Sunday"]', 3, 'Friday, then Saturday, then Sunday. Two days later is Sunday.'),
(1, 'logic', 'Which day of the week is between Monday and Wednesday?', '["Tuesday", "Thursday", "Sunday", "Friday"]', 0, 'The days go Monday, Tuesday, Wednesday, so Tuesday is in between.'),
(1, 'logic', 'Ravi has a swimming lesson every Tuesday. Today is Sunday. How many days until his lesson?', '["1", "2", "3", "4"]', 1, 'Sunday to Monday is 1 day and Monday to Tuesday is another, so 2 days.'),
(1, 'logic', 'Grandma is visiting on Friday. Today is Monday. How many days until she visits?', '["3", "5", "4", "6"]', 2, 'Count Tuesday, Wednesday, Thursday, Friday. That is 4 days.'),
(1, 'logic', 'Zara borrows a library book on Wednesday and must return it 7 days later. Which day is that?', '["Tuesday", "Thursday", "Wednesday", "Sunday"]', 2, 'A week has 7 days, so 7 days later is the same weekday: Wednesday.'),
(1, 'logic', 'Today is Friday. What day was it 4 days ago?', '["Monday", "Tuesday", "Sunday", "Wednesday"]', 0, 'Going back from Friday: Thursday, Wednesday, Tuesday, Monday.'),
(1, 'logic', 'The day after tomorrow is Sunday. What day is today?', '["Saturday", "Friday", "Thursday", "Monday"]', 1, 'Sunday is 2 days away. Today plus 2 days is Sunday, so today is Friday.'),
(1, 'logic', 'The day before yesterday was Monday. What day is today?', '["Tuesday", "Thursday", "Sunday", "Wednesday"]', 3, 'Two days after Monday is Wednesday.'),
(1, 'logic', 'Which day is 3 days after Saturday?', '["Monday", "Tuesday", "Wednesday", "Sunday"]', 1, 'After Saturday come Sunday, Monday, Tuesday. The third one is Tuesday.'),
(1, 'logic', 'Kim''s birthday is on Saturday, and her party is 2 days before that. Which day is the party?', '["Friday", "Sunday", "Thursday", "Wednesday"]', 2, 'Back from Saturday: Friday, then Thursday. The party is on Thursday.'),
(1, 'logic', 'Which day comes right before Saturday?', '["Sunday", "Thursday", "Monday", "Friday"]', 3, 'Friday is the day just before Saturday.'),
(1, 'logic', 'It is Sunday today. How many days until the next Sunday?', '["7", "6", "5", "1"]', 0, 'A whole week is 7 days, so the next Sunday is 7 days away.'),
(1, 'logic', 'Which month comes right after March?', '["February", "May", "April", "June"]', 2, 'The months go March, April, May. April follows March.'),
(1, 'logic', 'Which month comes just before June?', '["May", "July", "April", "August"]', 0, 'May comes right before June.'),
(1, 'logic', 'Which is the last month of the year?', '["November", "December", "January", "October"]', 1, 'The year ends with December.'),
