(1, 'logic', 'How many legs do 3 dogs have altogether?', '["12", "9", "6", "8"]', 0, 'Each dog has 4 legs, and 3 x 4 = 12.'),
(1, 'logic', 'A spider has 8 legs. How many legs do 2 spiders have altogether?', '["10", "8", "18", "16"]', 3, 'Two spiders with 8 legs each make 8 + 8 = 16.'),
(1, 'logic', 'How many wheels do 3 bicycles have altogether?', '["3", "5", "6", "9"]', 2, 'Each bicycle has 2 wheels, and 2 + 2 + 2 = 6.'),
(1, 'logic', 'How many wheels do 2 cars have altogether?', '["4", "8", "6", "10"]', 1, 'Each car has 4 wheels, and 4 + 4 = 8.'),
(1, 'logic', 'How many eyes do 4 cats have altogether?', '["8", "4", "6", "12"]', 0, 'Each cat has 2 eyes, and 4 x 2 = 8.'),
