(1, 'logic', 'How many days are there in three weeks?', '["14", "20", "21", "28"]', 2, 'Each week has 7 days, and 7 + 7 + 7 = 21.'),
(1, 'logic', 'An egg carton has 2 rows with 6 eggs in each row. How many eggs are in the carton?', '["8", "10", "14", "12"]', 3, 'Two rows of 6 eggs make 6 + 6 = 12.'),
(1, 'logic', 'How many corners do 2 squares have altogether?', '["4", "8", "6", "10"]', 1, 'A square has 4 corners, so 4 + 4 = 8.'),
(1, 'logic', 'Ella sees 2 bicycles and 1 tricycle. How many wheels is that altogether?', '["7", "5", "6", "8"]', 0, 'Two bicycles have 4 wheels and the tricycle has 3. And 4 + 3 = 7.'),
