(1, 'logic', 'Kenji has 12 shoes in a pile. How many pairs of shoes is that?', '["6", "4", "8", "12"]', 0, 'Each pair is 2 shoes, and 12 divided by 2 is 6.'),
(1, 'logic', 'How many times does the letter A appear in the word BANANA?', '["2", "3", "4", "6"]', 1, 'B-A-N-A-N-A has an A in the 2nd, 4th and 6th places, so 3 As.'),
(1, 'logic', 'How many fingers are there on two hands?', '["8", "5", "10", "12"]', 2, 'Each hand has 5 fingers, and 5 + 5 = 10.'),
(1, 'logic', 'There are 10 apples in a basket. Aria takes 4. How many are left in the basket?', '["4", "5", "6", "14"]', 2, 'Taking 4 away from 10 leaves 10 - 4 = 6.'),
(1, 'logic', 'A pizza is cut into 8 slices. Sam eats 3 slices. How many slices are left?', '["4", "5", "11", "3"]', 1, 'Eating 3 of the 8 slices leaves 8 - 3 = 5.'),
(1, 'logic', 'Tom has 5 marbles. His friend gives him 4 more. How many marbles does Tom have now?', '["8", "1", "10", "9"]', 3, 'Getting 4 more marbles gives 5 + 4 = 9.'),
(1, 'logic', 'There are 3 bags with 4 candies in each bag. How many candies are there in all?', '["12", "7", "9", "15"]', 0, '4 + 4 + 4 = 12.'),
(1, 'logic', 'Zoe has 12 stickers and gives half of them to her brother. How many does she keep?', '["4", "3", "6", "8"]', 2, 'Half of 12 is 6, so she keeps 6.'),
(1, 'logic', 'Ben has 2 more marbles than Ana. Ana has 6 marbles. How many does Ben have?', '["4", "7", "12", "8"]', 3, '2 more than 6 is 8.'),
(1, 'logic', 'Lily has 3 fewer cookies than Raj. Raj has 9 cookies. How many does Lily have?', '["6", "12", "7", "3"]', 0, '3 fewer than 9 is 9 - 3 = 6.'),
(1, 'logic', 'I am thinking of a number. If I add 3, I get 10. What is my number?', '["13", "7", "6", "8"]', 1, 'Work backward: 10 - 3 = 7.'),
(1, 'logic', 'I am thinking of a number. If I take away 4, I get 5. What is my number?', '["1", "8", "9", "10"]', 2, 'Work backward: 5 + 4 = 9.'),
(1, 'logic', 'There are 9 birds on a wire. 4 fly away, then 2 more land. How many birds are on the wire now?', '["5", "3", "11", "7"]', 3, '9 - 4 = 5, then 5 + 2 = 7.'),
